source_texts.nearest_pair_gap:
to main:
    let count_input be ask for a number ""
    let count be value of count_input
    let values be an empty list of number
    repeat count times:
        let value_input be ask for a number ""
        add (value of value_input) to values
    let best be (item 1 of values) - (item 2 of values)
    if best is less than 0:
        set best to 0 - best
    for each first from 1 to count - 1:
        for each second from first + 1 to count:
            let gap be (item first of values) - (item second of values)
            if gap is less than 0:
                set gap to 0 - gap
            if gap is less than best:
                set best to gap
    say best

source_texts.sorted_unique_numbers:
to main:
    let count_input be ask for a number ""
    let count be value of count_input
    let values be an empty list of number
    repeat count times:
        let input_number be ask for a number ""
        let number_value be value of input_number
        let already_seen be no
        for each position from 1 to length of values:
            if item position of values is number_value:
                set already_seen to yes
        if not already_seen:
            add number_value to values
    for each left from 1 to length of values:
        for each right from left + 1 to length of values:
            if item right of values is less than item left of values:
                let saved be item left of values
                set item left of values to item right of values
                set item right of values to saved
    let output be an empty list of text
    for each position from 1 to length of values:
        add item position of values to output
    say output joined with ","

