source_texts.polynomial_value:
import sys


def main():
    values = [int(line) for line in sys.stdin]
    degree = values[0]
    result = 0
    for coefficient in values[1:degree + 2]:
        result = result * values[degree + 2] + coefficient
    print(result)


if __name__ == "__main__":
    main()

source_texts.inventory_ledger:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    count = int(lines[0])
    balances = {}
    for line in lines[1:count + 1]:
        name, delta = line.split()
        balances[name] = balances.get(name, 0) + int(delta)
    print(",".join(f"{name}:{balances[name]}" for name in sorted(balances)))


if __name__ == "__main__":
    main()

