if __name__ == "__main__":
    main()

source_texts.sparse_dot_product:
import sys


def main():
    lines = iter(sys.stdin.read().splitlines())
    first_count = int(next(lines))
    first = {}
    for _ in range(first_count):
        index, value = map(int, next(lines).split())
        first[index] = value
    second_count = int(next(lines))
    total = 0
    for _ in range(second_count):
        index, value = map(int, next(lines).split())
        total += first.get(index, 0) * value
    print(total)


if __name__ == "__main__":
    main()

source_texts.postfix_evaluation:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    count = int(lines[0])
    stack = []
    for token in lines[1:count + 1]:
        if token in {"+", "-", "*"}:
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            else:
                stack.append(left * right)
        else:
            stack.append(int(token))
    print(stack[-1])


if __name__ == "__main__":
    main()

source_texts.caesar_shift:
import sys


def main():
    shift_line = sys.stdin.readline()
    shift = int(shift_line)
    text = sys.stdin.readline().rstrip("\n")
    result = "".join(chr((ord(letter) - ord("a") + shift) % 26 + ord("a"))
                     for letter in text)
    print(result)


if __name__ == "__main__":
    main()

source_texts.balanced_brackets:
import sys


def main():
    text = sys.stdin.readline().rstrip("\n")
    matching = {")": "(", "]": "[", "}": "{"}
    stack = []
    for character in text:
        if character in "([{":
            stack.append(character)
        elif not stack or stack.pop() != matching[character]:
            print("no")
            return
    print("yes" if not stack else "no")


if __name__ == "__main__":
    main()

