use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let line = input.lines().next().unwrap_or("");
    let mut stack = Vec::new();
    let valid = line.bytes().all(|bracket| match bracket {
        b'(' | b'[' | b'{' => { stack.push(bracket); true }
        b')' => stack.pop() == Some(b'('),
        b']' => stack.pop() == Some(b'['),
        b'}' => stack.pop() == Some(b'{'),
        _ => false,
    }) && stack.is_empty();
    println!("{}", if valid { "yes" } else { "no" });
}

sources.binary_search_queries:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let values: Vec<i128> = (0..n).map(|_| tokens.next().unwrap().parse().unwrap()).collect();
    let q: usize = tokens.next().unwrap().parse().unwrap();
    let answers: Vec<String> = (0..q).map(|_| {
        let query: i128 = tokens.next().unwrap().parse().unwrap();
        match values.binary_search(&query) { Ok(index) => (index + 1).to_string(), Err(_) => "0".to_string() }
    }).collect();
    println!("{}", answers.join(","));
}

sources.caesar_shift:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let (key_line, text) = input.split_once('\n').unwrap_or((&input, ""));
    let key: u8 = key_line.trim_end_matches('\r').parse().unwrap();
    let text = text.strip_suffix('\n').unwrap_or(text);
    let text = text.strip_suffix('\r').unwrap_or(text);
    let shifted: String = text.bytes().map(|byte| ((byte - b'a' + key) % 26 + b'a') as char).collect();
    println!("{}", shifted);
}

sources.gregorian_date_validity:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let values: Vec<i128> = input.split_whitespace().map(|v| v.parse().unwrap()).collect();
    let (year, month, day) = (values[0], values[1], values[2]);
    let leap = year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
    let max_day = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if leap => 29,
        2 => 28,
        _ => 0,
    };
    println!("{}", if day >= 1 && day <= max_day { "yes" } else { "no" });
}

