fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut balances: BTreeMap<&str, i128> = BTreeMap::new();
    for _ in 0..n {
        let name = tokens.next().unwrap();
        let delta: i128 = tokens.next().unwrap().parse().unwrap();
        *balances.entry(name).or_insert(0) += delta;
    }
    println!("{}", balances.into_iter().map(|(name, value)| format!("{name}:{value}")).collect::<Vec<_>>().join(","));
}

sources.matrix_diagonal_difference:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let (mut main, mut opposite): (i128, i128) = (0, 0);
    for row in 0..n {
        for column in 0..n {
            let value: i128 = tokens.next().unwrap().parse().unwrap();
            if row == column { main += value; }
            if column == n - 1 - row { opposite += value; }
        }
    }
    println!("{}", (main - opposite).abs());
}

