use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values: Vec<i128> = input.split_whitespace().map(|v| v.parse().unwrap()).collect();
    values.remove(0);
    values.sort_unstable();
    let answer = values.windows(2).map(|pair| pair[1] - pair[0]).min().unwrap();
    println!("{}", answer);
}

sources.polynomial_value:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let degree: usize = values.next().unwrap().parse().unwrap();
    let mut result: i128 = 0;
    let coefficients: Vec<i128> = (0..=degree)
        .map(|_| values.next().unwrap().parse().unwrap())
        .collect();
    let x: i128 = values.next().unwrap().parse().unwrap();
    for coefficient in coefficients {
        result = result * x + coefficient;
    }
    println!("{}", result);
}

sources.postfix_evaluation:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut stack: Vec<i128> = Vec::new();
    for _ in 0..n {
        match tokens.next().unwrap() {
            operator @ ("+" | "-" | "*") => {
                let right = stack.pop().unwrap();
                let left = stack.pop().unwrap();
                stack.push(match operator { "+" => left + right, "-" => left - right, _ => left * right });
            }
            value => stack.push(value.parse().unwrap()),
        }
    }
    println!("{}", stack.pop().unwrap());
}

