use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut a = HashMap::new();
    for _ in 0..n { let i: u64 = it.next().unwrap().parse().unwrap(); let v: i128 = it.next().unwrap().parse().unwrap(); a.insert(i, v); }
    let m: usize = it.next().unwrap().parse().unwrap();
    let mut sum: i128 = 0;
    for _ in 0..m { let i: u64 = it.next().unwrap().parse().unwrap(); let v: i128 = it.next().unwrap().parse().unwrap(); if let Some(x) = a.get(&i) { sum += x * v; } }
    println!("{sum}");
}

