sources.gregorian_date_validity:
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap(); let mut it = input.split_whitespace();
    let year: i128 = it.next().unwrap().parse().unwrap(); let month: i128 = it.next().unwrap().parse().unwrap(); let day: i128 = it.next().unwrap().parse().unwrap();
    let leap = year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
    let max_day = match month { 1|3|5|7|8|10|12 => 31, 4|6|9|11 => 30, 2 if leap => 29, 2 => 28, _ => 0 };
    println!(if day >= 1 && day <= max_day { "yes" } else { "no" });
}

