sources.matrix_diagonal_difference:
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace(); let n: usize = it.next().unwrap().parse().unwrap(); let mut main = 0i128; let mut other = 0i128;
    for r in 0..n { for c in 0..n { let x: i128 = it.next().unwrap().parse().unwrap(); if r == c { main += x; } if c == n - 1 - r { other += x; } } }
    println!("{}", (main - other).abs());
}

