source_texts.matrix_diagonal_difference:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut main_sum: i128 = 0;
    let mut other_sum: i128 = 0;
    for row in 0..n {
        for col in 0..n {
            let value: i128 = it.next().unwrap().parse().unwrap();
            if row == col { main_sum += value; }
            if row + col == n.saturating_sub(1) { other_sum += value; }
        }
    }
    println!("{}", (main_sum - other_sum).abs());
}

