use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut first: HashMap<u128, i128> = HashMap::new();
    for _ in 0..n { first.insert(it.next().unwrap().parse().unwrap(), it.next().unwrap().parse().unwrap()); }
    let m: usize = it.next().unwrap().parse().unwrap();
    let mut answer: i128 = 0;
    for _ in 0..m {
        let index: u128 = it.next().unwrap().parse().unwrap();
        let value: i128 = it.next().unwrap().parse().unwrap();
        if let Some(left) = first.get(&index) { answer += left * value; }
    }
    println!("{answer}");
}

source_texts.binary_search_queries:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let values: Vec<i128> = (&mut it).take(n).map(|s| s.parse().unwrap()).collect();
    let q: usize = it.next().unwrap().parse().unwrap();
    let answers: Vec<String> = it.take(q).map(|s| {
        let query: i128 = s.parse().unwrap();
        match values.binary_search(&query) { Ok(i) => (i + 1).to_string(), Err(_) => "0".to_owned() }
    }).collect();
    println!("{}", answers.join(","));
}

