        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => if leap { 29 } else { 28 },
        _ => 0,
    };
    println!("{}", if day >= 1 && day <= maximum { "yes" } else { "no" });
}

