import sys


def main():
    text = sys.stdin.readline().rstrip("\n")
    matching = {")": "(", "]": "[", "}": "{"}
    stack = []
    for char in text:
        if char in "([{":
            stack.append(char)
        elif not stack or stack.pop() != matching[char]:
            print("no")
            return
    print("yes" if not stack else "no")


if __name__ == "__main__":
    main()

