import sys


def main():
    lines = iter(sys.stdin.read().splitlines())
    first_count = int(next(lines))
    first = {}
    for _ in range(first_count):
        index, value = map(int, next(lines).split())
        first[index] = value
    second_count = int(next(lines))
    total = 0
    for _ in range(second_count):
        index, value = map(int, next(lines).split())
        total += first.get(index, 0) * value
    print(total)


if __name__ == "__main__":
    main()

