def main():
    tokens = sys.stdin.read().splitlines()
    stack = []
    for token in tokens[1:]:
        if token in {"+", "-", "*"}:
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            else:
                stack.append(left * right)
        else:
            stack.append(int(token))
    print(stack[-1])


if __name__ == "__main__":
    main()

