use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let values: Vec<i128> = (0..n).map(|_| it.next().unwrap().parse().unwrap()).collect();
    let q: usize = it.next().unwrap().parse().unwrap();
    let answers: Vec<String> = (0..q).map(|_| {
        let x: i128 = it.next().unwrap().parse().unwrap();
        values.binary_search(&x).map(|i| i + 1).unwrap_or(0).to_string()
    }).collect();
    println!("{}", answers.join(","));
}

sources.caesar_shift:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let shift: u8 = lines.next().unwrap().trim().parse().unwrap();
    let text = lines.next().unwrap_or("");
    let result: String = text.bytes().map(|b| ((b - b'a' + shift) % 26 + b'a') as char).collect();
    println!("{result}");
}

sources.gregorian_date_validity:
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let values: Vec<i128> = input.split_whitespace().map(|s| s.parse().unwrap()).collect();
    let (year, month, day) = (values[0], values[1], values[2]);
    let leap = year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
    let maximum = match month { 1 | 3 | 5 | 7 | 8 | 10 | 12 => 31, 4 | 6 | 9 | 11 => 30, 2 if leap => 29, 2 => 28, _ => 0 };
    println!("{}", if day >= 1 && day <= maximum { "yes" } else { "no" });
}

