use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut first = HashMap::new();
    for _ in 0..n { let index: u128 = it.next().unwrap().parse().unwrap(); let value: i128 = it.next().unwrap().parse().unwrap(); first.insert(index, value); }
    let m: usize = it.next().unwrap().parse().unwrap();
    let mut total = 0i128;
    for _ in 0..m { let index: u128 = it.next().unwrap().parse().unwrap(); let value: i128 = it.next().unwrap().parse().unwrap(); if let Some(left) = first.get(&index) { total += left * value; } }
    println!("{total}");
}

