import sys


def main():
    tokens = sys.stdin.read().split()
    n = int(tokens[0])
    stack = []
    for token in tokens[1:n + 1]:
        if token in {'+', '-', '*'}:
            right = stack.pop()
            left = stack.pop()
            stack.append(left + right if token == '+' else left - right if token == '-' else left * right)
        else:
            stack.append(int(token))
    print(stack[-1])


if __name__ == '__main__':
    main()

