import sys


def main():
    lines = iter(sys.stdin.read().splitlines())
    n = int(next(lines))
    first = {}
    for _ in range(n):
        index, value = map(int, next(lines).split())
        first[index] = value
    m = int(next(lines))
    total = 0
    for _ in range(m):
        index, value = map(int, next(lines).split())
        total += first.get(index, 0) * value
    print(total)


if __name__ == '__main__':
    main()

