use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut balances: BTreeMap<&str, i128> = BTreeMap::new();
    for _ in 0..n {
        let name = it.next().unwrap();
        let delta: i128 = it.next().unwrap().parse().unwrap();
        *balances.entry(name).or_insert(0) += delta;
    }
    println!("{}", balances.iter().map(|(k, v)| format!("{}:{}", k, v)).collect::<Vec<_>>().join(","));
}

source_texts.polynomial_value:
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let d: usize = it.next().unwrap().parse().unwrap();
    let mut value: i128 = it.next().unwrap().parse().unwrap();
    let coefficients: Vec<i128> = (0..d).map(|_| it.next().unwrap().parse().unwrap()).collect();
    let x: i128 = it.next().unwrap().parse().unwrap();
    for coefficient in coefficients { value = value * x + coefficient; }
    println!("{}", value);
}

source_texts.caesar_shift:
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let (first, text) = input.split_once('\n').unwrap_or((&input, ""));
    let k: u8 = first.trim_end_matches('\r').parse().unwrap();
    let text = text.strip_suffix('\n').unwrap_or(text);
    let text = text.strip_suffix('\r').unwrap_or(text);
    let shifted: String = text.bytes().map(|b| ((b - b'a' + k) % 26 + b'a') as char).collect();
    println!("{}", shifted);
}

source_texts.matrix_diagonal_difference:
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut main = 0i128; let mut opposite = 0i128;
    for row in 0..n { for col in 0..n { let v: i128 = it.next().unwrap().parse().unwrap(); if row == col { main += v; } if row + col + 1 == n { opposite += v; } } }
    println!("{}", (main - opposite).abs());
}

