use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap(); let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap(); let values: Vec<i128> = (0..n).map(|_| it.next().unwrap().parse().unwrap()).collect();
    let q: usize = it.next().unwrap().parse().unwrap(); let mut answers = Vec::with_capacity(q);
    for _ in 0..q { let x: i128 = it.next().unwrap().parse().unwrap(); answers.push(match values.binary_search(&x) { Ok(i) => (i + 1).to_string(), Err(_) => "0".to_string() }); }
    println!("{}", answers.join(","));
}

source_texts.postfix_evaluation:
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap(); let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap(); let mut stack: Vec<i128> = Vec::new();
    for _ in 0..n { match it.next().unwrap() { "+" => { let b = stack.pop().unwrap(); let a = stack.pop().unwrap(); stack.push(a + b); }, "-" => { let b = stack.pop().unwrap(); let a = stack.pop().unwrap(); stack.push(a - b); }, "*" => { let b = stack.pop().unwrap(); let a = stack.pop().unwrap(); stack.push(a * b); }, token => stack.push(token.parse().unwrap()), } }
    println!("{}", stack[0]);
}

source_texts.sparse_dot_product:
use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap(); let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap(); let mut a = HashMap::with_capacity(n);
    for _ in 0..n { let index: u128 = it.next().unwrap().parse().unwrap(); let value: i128 = it.next().unwrap().parse().unwrap(); a.insert(index, value); }
    let m: usize = it.next().unwrap().parse().unwrap(); let mut sum = 0i128;
    for _ in 0..m { let index: u128 = it.next().unwrap().parse().unwrap(); let value: i128 = it.next().unwrap().parse().unwrap(); if let Some(&left) = a.get(&index) { sum += left * value; } }
    println!("{}", sum);
}

