use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let line = input.lines().next().unwrap_or(""); let mut stack = Vec::new(); let mut valid = true;
    for ch in line.bytes() { match ch { b'(' | b'[' | b'{' => stack.push(ch), b')' => valid &= stack.pop() == Some(b'('), b']' => valid &= stack.pop() == Some(b'['), b'}' => valid &= stack.pop() == Some(b'{'), _ => {} } }
    println!("{}", if valid && stack.is_empty() { "yes" } else { "no" });
}

