use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap(); let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap(); let values: Vec<i128> = (0..n).map(|_| it.next().unwrap().parse().unwrap()).collect();
    let q: usize = it.next().unwrap().parse().unwrap(); let mut answers = Vec::with_capacity(q);
    for _ in 0..q { let x: i128 = it.next().unwrap().parse().unwrap(); answers.push(match values.binary_search(&x) { Ok(i) => (i + 1).to_string(), Err(_) => "0".to_string() }); }
    println!("{}", answers.join(","));
}

sources.caesar_shift:
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let (first, text) = input.split_once('\n').unwrap_or((&input, ""));
    let k: u8 = first.trim_end_matches('\r').parse().unwrap();
    let text = text.strip_suffix('\n').unwrap_or(text);
    let text = text.strip_suffix('\r').unwrap_or(text);
    let shifted: String = text.bytes().map(|b| ((b - b'a' + k) % 26 + b'a') as char).collect();
    println!("{}", shifted);
}

sources.gregorian_date_validity:
use std::io::{self, Read};

fn main() {
    let mut input = String::new(); io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let year: i128 = it.next().unwrap().parse().unwrap(); let month: i128 = it.next().unwrap().parse().unwrap(); let day: i128 = it.next().unwrap().parse().unwrap();
    let leap = year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
    let max_day = match month { 1|3|5|7|8|10|12 => 31, 4|6|9|11 => 30, 2 => if leap { 29 } else { 28 }, _ => 0 };
    println!("{}", if day >= 1 && day <= max_day { "yes" } else { "no" });
}

